public class ExchangeRateClient {

    private static final String ENDPOINT = 'callout:FB_Exchange_Rates/v1/latest';
    private static final Pattern CURRENCY_PATTERN = Pattern.compile('^[A-Z]{3}$');

    public class ExchangeRateException extends Exception {}

    public static Map<String, Decimal> getRates(String baseCurrency, Set<String> quoteCurrencies) {
        String base = normaliseCurrency(baseCurrency, 'Base currency');

        if (quoteCurrencies == null || quoteCurrencies.isEmpty()) {
            throw new ExchangeRateException('At least one quote currency is required.');
        }

        Set<String> quotes = new Set<String>();
        for (String quote : quoteCurrencies) {
            quotes.add(normaliseCurrency(quote, 'Quote currency'));
        }
        List<String> quoteList = new List<String>(quotes);

        HttpRequest request = new HttpRequest();
        request.setMethod('GET');
        request.setEndpoint(
            ENDPOINT
            + '?base=' + EncodingUtil.urlEncode(base, 'UTF-8')
            + '&symbols=' + EncodingUtil.urlEncode(String.join(quoteList, ','), 'UTF-8')
        );
        request.setHeader('Accept', 'application/json');

        Http http = new Http();
        HttpResponse response;
        try {
            response = http.send(request);
            if (response.getStatusCode() == 503) {
                response = http.send(request);
            }
        } catch (System.CalloutException e) {
            throw new ExchangeRateException('Exchange rate callout failed: ' + e.getMessage());
        }

        Integer status = response.getStatusCode();
        if (status != 200) {
            throw new ExchangeRateException('Exchange rate service returned HTTP ' + status + '.');
        }

        Map<String, Decimal> result = new Map<String, Decimal>();
        try {
            Map<String, Object> body = (Map<String, Object>) JSON.deserializeUntyped(response.getBody());
            Object ratesObject = body.get('rates');
            if (ratesObject == null) {
                throw new ExchangeRateException('Response body is missing the rates object.');
            }
            Map<String, Object> rates = (Map<String, Object>) ratesObject;
            for (String code : quotes) {
                Object rate = rates.get(code);
                if (rate == null) {
                    throw new ExchangeRateException('No rate returned for currency ' + code + '.');
                }
                result.put(code, Decimal.valueOf(String.valueOf(rate)));
            }
        } catch (ExchangeRateException e) {
            throw e;
        } catch (Exception e) {
            throw new ExchangeRateException('Unable to parse exchange rate response: ' + e.getMessage());
        }

        return result;
    }

    private static String normaliseCurrency(String currencyCode, String label) {
        if (currencyCode == null) {
            throw new ExchangeRateException(label + ' is required.');
        }
        String normalised = currencyCode.trim().toUpperCase();
        if (!CURRENCY_PATTERN.matcher(normalised).matches()) {
            throw new ExchangeRateException('Invalid ' + label.toLowerCase() + ': ' + currencyCode);
        }
        return normalised;
    }
}
