/**
 * ContactDomainService
 *
 * Groups Contacts by the domain part of their Email address.
 *
 * The class runs in `with sharing` mode so that the running user's sharing
 * rules (org-wide defaults, role hierarchy, sharing rules, manual shares) are
 * enforced for the Contact records that are returned.
 */
public with sharing class ContactDomainService {

    /**
     * Returns the Contacts belonging to the given Accounts, grouped by the
     * lower-cased domain part of their Email address.
     *
     * - `Jane@Example.COM` is grouped under the key `example.com`.
     * - Contacts without an Email (null, blank or missing an `@`) are omitted.
     * - A null or empty `accountIds` set returns an empty map.
     * - Every Contact returned has Id, Email and AccountId populated.
     *
     * @param accountIds Ids of the Accounts whose Contacts should be grouped.
     * @return Map of lower-cased email domain -> Contacts in that domain.
     */
    public static Map<String, List<Contact>> groupByEmailDomain(Set<Id> accountIds) {
        Map<String, List<Contact>> contactsByDomain = new Map<String, List<Contact>>();

        if (accountIds == null || accountIds.isEmpty()) {
            return contactsByDomain;
        }

        // Single bulkified query: no SOQL/DML inside loops.
        List<Contact> contacts = [
            SELECT Id, Email, AccountId
            FROM Contact
            WHERE AccountId IN :accountIds
              AND Email != null
            ORDER BY Id
        ];

        for (Contact c : contacts) {
            String domain = extractDomain(c.Email);
            if (domain == null) {
                continue;
            }

            if (!contactsByDomain.containsKey(domain)) {
                contactsByDomain.put(domain, new List<Contact>());
            }
            contactsByDomain.get(domain).add(c);
        }

        return contactsByDomain;
    }

    /**
     * Extracts the lower-cased domain from an email address.
     * Returns null when no usable domain can be determined.
     */
    private static String extractDomain(String email) {
        if (String.isBlank(email)) {
            return null;
        }

        Integer atIndex = email.indexOf('@');
        if (atIndex == -1 || atIndex == email.length() - 1) {
            return null;
        }

        String domain = email.substring(atIndex + 1).trim().toLowerCase(Locale.ENGLISH);
        return String.isBlank(domain) ? null : domain;
    }
}
