public with sharing class RecordSearchService {
    public class SearchException extends Exception {}

    private static final Integer MIN_ROWS = 1;
    private static final Integer MAX_ROWS = 200;

    public static List<SObject> search(
        String objectApiName,
        List<String> fields,
        Map<String, Object> filters,
        String orderByField,
        Integer maxRows
    ) {
        // Validate objectApiName
        if (String.isBlank(objectApiName)) {
            throw new SearchException('Object API name is required.');
        }

        // Validate maxRows
        if (maxRows == null || maxRows < MIN_ROWS || maxRows > MAX_ROWS) {
            throw new SearchException('maxRows must be between ' + MIN_ROWS + ' and ' + MAX_ROWS + '.');
        }

        // Validate fields
        if (fields == null || fields.isEmpty()) {
            throw new SearchException('At least one field must be requested.');
        }

        // Resolve SObjectType case-insensitively
        Schema.SObjectType sObjType = getSObjectType(objectApiName);
        if (sObjType == null) {
            throw new SearchException('Object not found: ' + objectApiName);
        }
        Schema.DescribeSObjectResult objDescribe = sObjType.getDescribe();

        // Check object accessibility
        if (!objDescribe.isAccessible()) {
            throw new SearchException('You do not have read access to object ' + objDescribe.getName() + '.');
        }

        Map<String, Schema.SObjectField> fieldMap = objDescribe.fields.getMap();

        // Build select fields: Id plus requested fields, deduped case-insensitively
        List<String> selectFieldNames = new List<String>{'Id'};
        Set<String> seenFields = new Set<String>{'id'};
        for (String f : fields) {
            if (String.isBlank(f)) {
                throw new SearchException('Field name cannot be blank.');
            }
            Schema.SObjectField field = resolveField(fieldMap, f);
            if (field == null) {
                throw new SearchException('Field not found: ' + f);
            }
            Schema.DescribeFieldResult fieldDescribe = field.getDescribe();
            if (!fieldDescribe.isAccessible()) {
                throw new SearchException('You do not have read access to field ' + fieldDescribe.getName() + '.');
            }
            String actualName = fieldDescribe.getName();
            if (!seenFields.contains(actualName.toLowerCase())) {
                seenFields.add(actualName.toLowerCase());
                selectFieldNames.add(actualName);
            }
        }

        // Build WHERE clause
        List<String> whereClauses = new List<String>();
        Map<String, Object> bindMap = new Map<String, Object>();
        Integer bindIndex = 0;

        if (filters != null && !filters.isEmpty()) {
            for (String filterField : filters.keySet()) {
                if (String.isBlank(filterField)) {
                    throw new SearchException('Filter field name cannot be blank.');
                }
                Schema.SObjectField field = resolveField(fieldMap, filterField);
                if (field == null) {
                    throw new SearchException('Filter field not found: ' + filterField);
                }
                Schema.DescribeFieldResult fieldDescribe = field.getDescribe();
                if (!fieldDescribe.isAccessible()) {
                    throw new SearchException('You do not have read access to field ' + fieldDescribe.getName() + '.');
                }
                if (!fieldDescribe.isFilterable()) {
                    throw new SearchException('Field ' + fieldDescribe.getName() + ' cannot be filtered.');
                }
                Object filterValue = filters.get(filterField);
                if (filterValue == null) {
                    whereClauses.add(fieldDescribe.getName() + ' = null');
                } else {
                    String bindName = 'v' + bindIndex;
                    bindIndex++;
                    whereClauses.add(fieldDescribe.getName() + ' = :' + bindName);
                    bindMap.put(bindName, filterValue);
                }
            }
        }

        // Build ORDER BY clause
        String orderByClause = '';
        if (!String.isBlank(orderByField)) {
            Schema.SObjectField field = resolveField(fieldMap, orderByField);
            if (field == null) {
                throw new SearchException('Order-by field not found: ' + orderByField);
            }
            Schema.DescribeFieldResult fieldDescribe = field.getDescribe();
            if (!fieldDescribe.isAccessible()) {
                throw new SearchException('You do not have read access to field ' + fieldDescribe.getName() + '.');
            }
            if (!fieldDescribe.isSortable()) {
                throw new SearchException('Field ' + fieldDescribe.getName() + ' cannot be sorted.');
            }
            orderByClause = ' ORDER BY ' + fieldDescribe.getName() + ' ASC';
        }

        // Build final query
        String query = 'SELECT ' + String.join(selectFieldNames, ', ') + ' FROM ' + objDescribe.getName();
        if (!whereClauses.isEmpty()) {
            query += ' WHERE ' + String.join(whereClauses, ' AND ');
        }
        query += orderByClause;
        query += ' LIMIT ' + maxRows;

        try {
            return Database.queryWithBinds(query, bindMap, AccessLevel.USER_MODE);
        } catch (Exception e) {
            throw new SearchException('Search failed: ' + e.getMessage());
        }
    }

    private static Schema.SObjectType getSObjectType(String objectApiName) {
        Schema.SObjectType sObjType = Schema.getGlobalDescribe().get(objectApiName);
        if (sObjType != null) {
            return sObjType;
        }
        for (Schema.SObjectType t : Schema.getGlobalDescribe().values()) {
            if (t.getDescribe().getName().equalsIgnoreCase(objectApiName)) {
                return t;
            }
        }
        return null;
    }

    private static Schema.SObjectField resolveField(Map<String, Schema.SObjectField> fieldMap, String fieldName) {
        Schema.SObjectField field = fieldMap.get(fieldName);
        if (field != null) {
            return field;
        }
        for (Schema.SObjectField f : fieldMap.values()) {
            if (f.getDescribe().getName().equalsIgnoreCase(fieldName)) {
                return f;
            }
        }
        return null;
    }
}
