public with sharing class ContactLookupAction {
    @InvocableMethod(
        label='Find Contact by Email'
        description='Finds the earliest-created Contact with the given email address.'
    )
    public static List<Result> find(List<Request> requests) {
        List<Result> results = new List<Result>();
        if (requests == null) {
            return results;
        }

        // Collect unique, non-blank, normalized emails for a single SOQL query.
        Set<String> uniqueEmails = new Set<String>();
        for (Request req : requests) {
            String email = (req == null) ? null : req.email;
            if (String.isNotBlank(email)) {
                uniqueEmails.add(email.trim().toLowerCase());
            }
        }

        // Query once for all unique emails. Salesforce Email fields match case-insensitively.
        // Order by CreatedDate so the first contact seen per email is the earliest.
        Map<String, Id> contactIdByEmail = new Map<String, Id>();
        if (!uniqueEmails.isEmpty()) {
            List<Contact> contacts = [
                SELECT Id, Email, CreatedDate
                FROM Contact
                WHERE Email IN :uniqueEmails
                ORDER BY CreatedDate ASC, Id ASC
            ];

            for (Contact c : contacts) {
                if (c.Email == null) {
                    continue;
                }
                String normalized = c.Email.trim().toLowerCase();
                if (!contactIdByEmail.containsKey(normalized)) {
                    contactIdByEmail.put(normalized, c.Id);
                }
            }
        }

        // Build exactly one Result per Request, preserving input order.
        for (Request req : requests) {
            Result res = new Result();
            String email = (req == null) ? null : req.email;
            String normalized = (email == null) ? null : email.trim().toLowerCase();

            if (String.isNotBlank(normalized) && contactIdByEmail.containsKey(normalized)) {
                res.contactId = contactIdByEmail.get(normalized);
                res.found = true;
            } else {
                res.contactId = null;
                res.found = false;
            }

            results.add(res);
        }

        return results;
    }

    public class Request {
        @InvocableVariable(label='Email' required=true)
        public String email;
    }

    public class Result {
        @InvocableVariable(label='Contact ID')
        public Id contactId;

        @InvocableVariable(label='Found')
        public Boolean found;
    }
}
