public with sharing class PicklistService {
    public class Option {
        public String value;
        public String label;
        public Boolean isDefault;

        public Option(String value, String label, Boolean isDefault) {
            this.value = value;
            this.label = label;
            this.isDefault = isDefault;
        }
    }

    public class PicklistServiceException extends Exception {}

    public static List<PicklistService.Option> activeOptions(String objectApiName, String fieldApiName) {
        if (String.isBlank(objectApiName) || String.isBlank(fieldApiName)) {
            throw new PicklistServiceException('Object and field API names are required.');
        }

        String objName = objectApiName.trim();
        String fldName = fieldApiName.trim();

        Schema.SObjectType sObjType = getSObjectType(objName);
        if (sObjType == null) {
            throw new PicklistServiceException('Object not found: ' + objName);
        }

        Schema.DescribeSObjectResult objDescribe;
        try {
            objDescribe = sObjType.getDescribe();
        } catch (Exception e) {
            throw new PicklistServiceException('Unable to describe object: ' + objName);
        }

        Map<String, Schema.SObjectField> fields = objDescribe.fields.getMap();
        Schema.SObjectField field = fields.get(fldName);
        if (field == null) {
            field = fields.get(fldName.toLowerCase());
        }
        if (field == null) {
            for (String key : fields.keySet()) {
                if (key.equalsIgnoreCase(fldName)) {
                    field = fields.get(key);
                    break;
                }
            }
        }
        if (field == null) {
            throw new PicklistServiceException('Field not found: ' + fldName + ' on ' + objName);
        }

        Schema.DescribeFieldResult fieldDescribe;
        try {
            fieldDescribe = field.getDescribe();
        } catch (Exception e) {
            throw new PicklistServiceException('Unable to describe field: ' + fldName);
        }

        Schema.DisplayType dt = fieldDescribe.getType();
        if (dt != Schema.DisplayType.PICKLIST && dt != Schema.DisplayType.MULTIPICKLIST) {
            throw new PicklistServiceException('Field is not a picklist: ' + fldName);
        }

        List<PicklistService.Option> options = new List<PicklistService.Option>();
        for (Schema.PicklistEntry entry : fieldDescribe.getPicklistValues()) {
            if (entry.isActive()) {
                options.add(new PicklistService.Option(
                    entry.getValue(),
                    entry.getLabel(),
                    entry.isDefaultValue()
                ));
            }
        }
        return options;
    }

    private static Schema.SObjectType getSObjectType(String objectApiName) {
        Map<String, Schema.SObjectType> globalDescribe = Schema.getGlobalDescribe();
        Schema.SObjectType sObjType = globalDescribe.get(objectApiName);
        if (sObjType != null) {
            return sObjType;
        }
        sObjType = globalDescribe.get(objectApiName.toLowerCase());
        if (sObjType != null) {
            return sObjType;
        }
        String lower = objectApiName.toLowerCase();
        for (String key : globalDescribe.keySet()) {
            if (key.toLowerCase() == lower) {
                return globalDescribe.get(key);
            }
        }
        return null;
    }
}
