/**
 * Chunked Account re-rating job.
 *
 * Each execution handles at most the first 200 Ids of the list it was given,
 * derives Account.Rating from Account.AnnualRevenue, and - while Ids remain -
 * enqueues a new AccountScoringJob for the remainder, forming a chain that
 * keeps going until every Id has been processed.
 *
 * A single execution performs exactly one SOQL query and one DML statement,
 * so the job is safe for bulk data (up to the 50,000 Ids the button supplies).
 */
public with sharing class AccountScoringJob implements Queueable {

    /** Maximum number of Account Ids handled by one execution. */
    private static final Integer BATCH_SIZE = 200;

    private static final String RATING_HOT = 'Hot';
    private static final String RATING_WARM = 'Warm';
    private static final String RATING_COLD = 'Cold';

    private static final Decimal HOT_THRESHOLD = 1000000;
    private static final Decimal WARM_THRESHOLD = 100000;

    /** Remaining Ids for this job; the first BATCH_SIZE are processed here. */
    private final List<Id> accountIds;

    /**
     * @param accountIds Ids to rate. The first 200 are processed by this
     *                   execution, the rest are handed to a chained job.
     */
    public AccountScoringJob(List<Id> accountIds) {
        this.accountIds = accountIds == null ? new List<Id>() : new List<Id>(accountIds);
    }

    /**
     * Rates the first 200 Accounts of the list and chains the remainder.
     * The QueueableContext is never assumed to be populated, because tests
     * (and callers) may invoke execute(null) directly.
     */
    public void execute(QueueableContext context) {
        if (accountIds.isEmpty()) {
            return;
        }

        List<Id> batchIds = firstBatchIds();

        // Exactly one SOQL query per execution.
        List<Account> accounts = [
            SELECT Id, AnnualRevenue
            FROM Account
            WHERE Id IN :batchIds
        ];

        for (Account account : accounts) {
            account.Rating = ratingFor(account.AnnualRevenue);
        }

        // Exactly one DML statement per execution.
        if (!accounts.isEmpty()) {
            update accounts;
        }

        // Chain the rest of the Ids so the whole list is eventually rated.
        if (accountIds.size() > BATCH_SIZE) {
            System.enqueueJob(new AccountScoringJob(remainingIds()));
        }
    }

    /**
     * Enqueues the first job of the chain.
     *
     * @param accountIds Ids to rate.
     * @return the enqueued job Id, or null when there is nothing to do.
     */
    public static Id start(List<Id> accountIds) {
        if (accountIds == null || accountIds.isEmpty()) {
            return null;
        }
        return System.enqueueJob(new AccountScoringJob(accountIds));
    }

    /** The first BATCH_SIZE Ids of this job's list (fewer if the list is short). */
    private List<Id> firstBatchIds() {
        Integer batchSize = Math.min(BATCH_SIZE, accountIds.size());
        List<Id> batchIds = new List<Id>();
        for (Integer i = 0; i < batchSize; i++) {
            batchIds.add(accountIds[i]);
        }
        return batchIds;
    }

    /** The Ids left over after this execution's batch. */
    private List<Id> remainingIds() {
        List<Id> remaining = new List<Id>();
        for (Integer i = BATCH_SIZE; i < accountIds.size(); i++) {
            remaining.add(accountIds[i]);
        }
        return remaining;
    }

    /** 1,000,000+ -> Hot, 100,000+ -> Warm, anything else (incl. blank) -> Cold. */
    private static String ratingFor(Decimal annualRevenue) {
        if (annualRevenue == null) {
            return RATING_COLD;
        }
        if (annualRevenue >= HOT_THRESHOLD) {
            return RATING_HOT;
        }
        if (annualRevenue >= WARM_THRESHOLD) {
            return RATING_WARM;
        }
        return RATING_COLD;
    }
}
