/**
 * Rolls up closed-won opportunity revenue per account for the current calendar year.
 *
 * The class is declared `with sharing` so that record-level sharing is enforced for
 * the running user; accounts they cannot see are never returned.
 */
public with sharing class OpportunityRollupService {

    /**
     * Returns, for each requested account, the sum of Amount over its won
     * opportunities (IsWon = true) whose CloseDate falls in the current calendar year.
     *
     * Every Id passed in is guaranteed to be a key of the returned map. An account with
     * no qualifying opportunities, or whose qualifying opportunities all have a blank
     * Amount, maps to 0 (never null). Ids that were not requested are never keys, and a
     * null or empty input returns an empty map.
     *
     * @param accountIds the accounts to roll up (may be null or empty)
     * @return Map<Id, Decimal> of account Id to won amount this year, never null values
     */
    public static Map<Id, Decimal> wonAmountThisYear(Set<Id> accountIds) {
        Map<Id, Decimal> wonAmountByAccount = new Map<Id, Decimal>();

        if (accountIds == null || accountIds.isEmpty()) {
            return wonAmountByAccount;
        }

        // Seed every requested account with 0 so callers always get a value, even when
        // the account has no qualifying opportunities.
        for (Id accountId : accountIds) {
            wonAmountByAccount.put(accountId, 0);
        }

        // A single aggregate query does the summing in the database; individual
        // Opportunity records are never loaded. THIS_YEAR resolves to the current
        // calendar year for the running user's date.
        for (AggregateResult aggregate : [
            SELECT AccountId, SUM(Amount) total
            FROM Opportunity
            WHERE IsWon = true
                AND CloseDate = THIS_YEAR
                AND AccountId IN :accountIds
            GROUP BY AccountId
        ]) {
            Id accountId = (Id) aggregate.get('AccountId');
            Decimal total = (Decimal) aggregate.get('total');

            // SUM() returns null when every qualifying Amount is blank.
            wonAmountByAccount.put(accountId, total == null ? 0 : total);
        }

        return wonAmountByAccount;
    }
}
