/**
 * Central application factory wiring the fflib layers (Domain, Selector,
 * Service, UnitOfWork) together. Tests may substitute mocks by calling
 * setMock(...) on the relevant factory field.
 */
public class Application {
    /**
     * Units of work for every SObject type that participates in a single
     * commit: new Accounts, Contacts and Opportunities belonging to those
     * Accounts, plus OpportunityContactRoles linking the new Opportunities
     * and Contacts. Registering all four types here lets the unit of work
     * resolve the relationships registered via registerRelationship /
     * registerNew(field, parent) within one commitWork().
     */
    public static final fflib_Application.UnitOfWorkFactory UnitOfWork =
        new fflib_Application.UnitOfWorkFactory(
            new List<Schema.SObjectType>{
                Account.SObjectType,
                Contact.SObjectType,
                Opportunity.SObjectType,
                OpportunityContactRole.SObjectType
            });

    /**
     * Service layer bindings: interface -> implementation.
     */
    public static final fflib_Application.ServiceFactory Service =
        new fflib_Application.ServiceFactory(
            new Map<Type, Type>{
                IAccountsService.class => AccountsServiceImpl.class
            });

    /**
     * Selector layer bindings: SObject type -> selector implementation.
     */
    public static final fflib_Application.SelectorFactory Selector =
        new fflib_Application.SelectorFactory(
            new Map<Schema.SObjectType, Type>{
                Account.SObjectType => AccountsSelector.class,
                Contact.SObjectType => ContactsSelector.class
            });

    /**
     * Domain layer bindings: SObject type -> domain constructable.
     * Passing the Selector factory here means
     * Application.Domain.newInstance(Set<Id>) loads its records through the
     * configured selectors (AccountsSelector for Account).
     */
    public static final fflib_Application.DomainFactory Domain =
        new fflib_Application.DomainFactory(
            Application.Selector,
            new Map<Schema.SObjectType, Type>{
                Account.SObjectType => Accounts.Constructor.class
            });
}
