     *
     * At most maxRecords rows are returned, in a single query (SOQL LIMIT). Each row
     * contains the selector's standard field list plus the parent account's Name.
     * The query is built from the selector's query factory so that the selector's field
     * list and security settings keep applying.
     *
     * @param accountIds the accounts whose open opportunities are returned
     * @param maxRecords the maximum number of rows returned
     */
    public List<Opportunity> selectTopOpenByAccountIds(Set<Id> accountIds, Integer maxRecords) {
        if (accountIds == null || accountIds.isEmpty() || maxRecords == null || maxRecords < 1) {
            return new List<Opportunity>();
        }

        fflib_QueryFactory queryFactory = newQueryFactory()
            .selectField('Account.Name')
            .setCondition('IsClosed = false AND AccountId IN :accountIds')
            .addOrdering('Amount', fflib_QueryFactory.SortOrder.DESCENDING, true)
            .addOrdering('CloseDate', fflib_QueryFactory.SortOrder.ASCENDING)
