File: force-app/main/default/classes/AccountOnboardingService.cls
```apex
/**
 * @description Service layer for onboarding Accounts together with their Contacts.
 *
 *              The whole onboarding runs as a single unit of work: one
 *              fflib_SObjectUnitOfWork is created, every record is registered on it
 *              and it is committed exactly once. No DML is performed directly by
 *              this class, which keeps the transaction consistent and bulk-safe for
 *              large numbers of records.
 */
public with sharing class AccountOnboardingService
{
    /**
     * @description Creates one Account per entry of the given map (the Account Name is
     *              the map key) and, for every last name in that entry's value, one
     *              Contact with that LastName related to the newly created Account.
     *
     * @param contactLastNamesByAccountName Account name -> list of Contact last names
     * @return The inserted Accounts with their Ids populated, or an empty list when the
     *         input is null or empty (in which case nothing is written)
     */
    public static List<Account> createAccountsWithContacts(Map<String, List<String>> contactLastNamesByAccountName)
    {
        List<Account> newAccounts = new List<Account>();

        if (contactLastNamesByAccountName == null || contactLastNamesByAccountName.isEmpty())
        {
            return newAccounts;
        }

        // Single unit of work for the whole operation. Parents are listed first so the
        // Accounts are inserted before the Contacts that reference them.
        fflib_SObjectUnitOfWork uow = new fflib_SObjectUnitOfWork(
            new List<Schema.SObjectType>{ Account.SObjectType, Contact.SObjectType }
        );

        for (String accountName : contactLastNamesByAccountName.keySet())
        {
            Account newAccount = new Account(Name = accountName);
            uow.registerNew(newAccount);
            newAccounts.add(newAccount);

            List<String> contactLastNames = contactLastNamesByAccountName.get(accountName);

            if (contactLastNames == null || contactLastNames.isEmpty())
            {
                continue;
            }

            for (String lastName : contactLastNames)
            {
                // The unit of work resolves Contact.AccountId once the Account has been
                // inserted. Contacts are still batched into one insert per SObject type,
                // so this stays bulk-safe for hundreds of records.
                uow.registerNew(new Contact(LastName = lastName), Contact.AccountId, newAccount);
            }
        }

        // One single commit for every record of the transaction.
        uow.commitWork();

        return newAccounts;
    }
}
