```apex
/**
 * Service that closes opportunities as won and tells Fulfilment about them
 * by publishing the Deal_Won__e platform event.
 *
 * The opportunity updates and the platform events are handled by a single
 * fflib unit of work: the events are registered as "after success" events,
 * so they are only published once the DML has been committed. If the save
 * fails, nothing is published and the exception propagates to the caller.
 */
public with sharing class OpportunityWinService {

    private static final String CLOSED_WON = 'Closed Won';

    /**
     * Marks the given opportunities as Closed Won (CloseDate = today) and
     * publishes one Deal_Won__e event per opportunity that was actually closed.
     *
     * @param opportunityIds the opportunities to close
     * @return the number of opportunities that were closed by this call
     */
    public static Integer markWon(Set<Id> opportunityIds) {

        if (opportunityIds == null || opportunityIds.isEmpty()) {
            return 0;
        }

        List<Opportunity> opportunities =
            OpportunitiesSelector.newInstance().selectById(opportunityIds);

        fflib_ISObjectUnitOfWork uow = Application.UnitOfWork.newInstance();

        Integer closedCount = 0;
        Date today = Date.today();

        for (Opportunity opportunity : opportunities) {

            // Already won, nothing to do and nothing to announce
            if (CLOSED_WON == opportunity.StageName) {
                continue;
            }

            opportunity.StageName = CLOSED_WON;
            opportunity.CloseDate = today;
            uow.registerDirty(opportunity);

            Deal_Won__e dealWon = new Deal_Won__e();
            dealWon.Opportunity_Id__c = opportunity.Id;
            dealWon.Amount__c = opportunity.Amount;

            // Published only after the opportunity DML has been committed
            // successfully, so Fulfilment never hears about an unsaved deal
            uow.registerPublishAfterSuccess(dealWon);

            closedCount++;
        }

        if (closedCount == 0) {
            return 0;
        }

        // One commit for the updates and the events. If the DML fails the
        // events are never published and the exception is thrown to the caller.
        uow.commitWork();

        return closedCount;
    }
}
