```apex
public with sharing class AccountRatingService {
    private static final Decimal HOT_THRESHOLD = 100000;
    private static final String HOT = 'Hot';
    private static final String WARM = 'Warm';
    private static final String COLD = 'Cold';

    @future
    public static void recalculate(Set<Id> accountIds) {
        if (accountIds == null || accountIds.isEmpty()) {
            return;
        }

        Set<Id> validAccountIds = new Set<Id>();
        for (Id accountId : accountIds) {
            if (accountId != null) {
                validAccountIds.add(accountId);
            }
        }
        if (validAccountIds.isEmpty()) {
            return;
        }

        Map<Id, Account> accountsById = new Map<Id, Account>([
            SELECT Id, Rating
            FROM Account
            WHERE Id IN :validAccountIds
        ]);

        Map<Id, String> ratingByAccountId = new Map<Id, String>();
        for (Id accountId : validAccountIds) {
            ratingByAccountId.put(accountId, COLD);
        }

        for (AggregateResult result : [
            SELECT AccountId, COUNT(Id) openCount, MAX(Amount) maxAmount
            FROM Opportunity
            WHERE AccountId IN :validAccountIds
              AND IsClosed = false
            GROUP BY AccountId
        ]) {
            Id accountId = (Id) result.get('AccountId');
            Integer openCount = (Integer) result.get('openCount');
            Decimal maxAmount = (Decimal) result.get('maxAmount');

            if (openCount != null && openCount > 0) {
                if (maxAmount != null && maxAmount >= HOT_THRESHOLD) {
                    ratingByAccountId.put(accountId, HOT);
                } else {
                    ratingByAccountId.put(accountId, WARM);
                }
            }
        }

        List<Account> accountsToUpdate = new List<Account>();
        for (Id accountId : ratingByAccountId.keySet()) {
            Account acc = accountsById.get(accountId);
            if (acc != null && acc.Rating != ratingByAccountId.get(accountId)) {
                acc.Rating = ratingByAccountId.get(accountId);
                accountsToUpdate.add(acc);
            }
        }

        if (!accountsToUpdate.isEmpty()) {
            update accountsToUpdate;
        }
    }
}
```

What I did differently and why: I did not make one `@future` call per Opportunity. Salesforce allows only 50 `@future` calls per transaction, so a CPQ batch of 200 opportunities would exceed that limit and fail. Instead, the trigger collects the unique `AccountId` values and makes a single `@future` call with a `Set<Id>`. The service then recalculates all affected accounts in one aggregate query and one DML update. I also recalculate the old account if an Opportunity’s `AccountId` changes, so the previous account’s `Rating` does not go stale.

