public with sharing class LeadContactMatcher {
    /**
     * Returns one Id per lead, in the same order as `leads`.
     *
     * I would use a Map instead of the nested loop here. The nested loop is very
     * readable, but 3,000 leads x 3,000 contacts is up to 9,000,000 comparisons
     * inside the import transaction, which can burn CPU time. Building a
     * normalized email -> first contact Id map is O(leads + contacts), keeps
     * "first contact wins" by only inserting the first occurrence of each
     * normalized email, and still does no SOQL or DML.
     */
    public static List<Id> matchByEmail(List<Lead> leads, List<Contact> contacts) {
        List<Id> matches = new List<Id>();

        if (leads == null || leads.isEmpty()) {
            return matches;
        }

        Map<String, Id> contactIdByEmail = new Map<String, Id>();

        if (contacts != null) {
            for (Contact c : contacts) {
                if (c == null) {
                    continue;
                }

                String email = normalizeEmail(c.Email);
                if (email == null) {
                    continue;
                }

                // Preserve the first contact in `contacts` order for duplicate emails.
                if (!contactIdByEmail.containsKey(email)) {
                    contactIdByEmail.put(email, c.Id);
                }
            }
        }

        for (Lead l : leads) {
            if (l == null) {
                matches.add(null);
                continue;
            }

            String email = normalizeEmail(l.Email);
            if (email == null) {
                matches.add(null);
                continue;
            }

            matches.add(contactIdByEmail.get(email));
        }

        return matches;
    }

    private static String normalizeEmail(String email) {
        if (email == null) {
            return null;
        }

        String normalized = email.trim().toLowerCase();
        return normalized.length() == 0 ? null : normalized;
    }
}
```

