/**
 * CaseTrigger
 *
 * After update trigger on Case.
 * When a Case transitions from not closed to closed and has a Contact, enqueue a
 * Queueable job to create a CSAT survey Task asynchronously.
 *
 * Bulk-safe: The nightly cleanup can close up to 200 Cases in a single transaction.
 * Enqueueing one Queueable job per Case would exceed the governor limit of 50
 * System.enqueueJob calls per synchronous transaction. Therefore, we enqueue a
 * single CaseSurveyJob with the set of Case IDs. The job processes each Case
 * independently and uses allOrNone=false so one failure does not affect the others.
 */
trigger CaseTrigger on Case (after update) {
    Set<Id> caseIds = new Set<Id>();
    for (Case newCase : Trigger.new) {
        Case oldCase = Trigger.oldMap.get(newCase.Id);
        // Only cases that changed from not closed to closed and have a contact.
        if (newCase.IsClosed && !oldCase.IsClosed && newCase.ContactId != null) {
            caseIds.add(newCase.Id);
        }
    }

    if (!caseIds.isEmpty()) {
        System.enqueueJob(new CaseSurveyJob(caseIds));
    }
}
