/**
 * CaseSurveyJob
 *
 * Queueable job that creates CSAT survey Tasks for closed Cases.
 * Receives a Set of Case IDs, queries the Cases to get CaseNumber and ContactId,
 * and inserts a Task for each Case.
 *
 * Uses Database.insert with allOrNone=false so that a failure on one Task does not
 * prevent the other Tasks from being inserted. This provides record-level isolation
 * even though a single job processes multiple Cases.
 *
 * Note: If the future vendor integration performs a callout per Case, this job may
 * need to be chunked to respect the 100 callout limit per transaction. For now, it
 * handles up to 200 Cases comfortably.
 */
public class CaseSurveyJob implements Queueable {
    private Set<Id> caseIds;

    public CaseSurveyJob(Set<Id> caseIds) {
        this.caseIds = caseIds;
    }

    public void execute(QueueableContext context) {
        // Re-query to get the latest data and ensure we only process Cases with a Contact.
        List<Case> cases = [
            SELECT Id, CaseNumber, ContactId
            FROM Case
            WHERE Id IN :caseIds
            AND ContactId != null
        ];

        List<Task> tasks = new List<Task>();
        Date surveyDate = Date.today().addDays(2);

        for (Case c : cases) {
            tasks.add(new Task(
                WhatId = c.Id,
                WhoId = c.ContactId,
                Subject = 'CSAT survey: ' + c.CaseNumber,
                ActivityDate = surveyDate,
                Status = 'Not Started'
            ));
        }

        if (!tasks.isEmpty()) {
            // allOrNone = false allows partial success.
            Database.insert(tasks, false);
        }
    }
}
```

