public with sharing class AccountCountrySync {
    public static void handleAfterUpdate(Map<Id, Account> newAccounts, Map<Id, Account> oldAccounts) {
        if (newAccounts == null || newAccounts.isEmpty() || oldAccounts == null) {
            return;
        }

        Set<Id> changedAccountIds = new Set<Id>();
        for (Account newAcc : newAccounts.values()) {
            Account oldAcc = oldAccounts.get(newAcc.Id);
            if (oldAcc == null) {
                continue;
            }
            if (!isSameCountry(newAcc.BillingCountry, oldAcc.BillingCountry)) {
                changedAccountIds.add(newAcc.Id);
            }
        }

        if (changedAccountIds.isEmpty()) {
            return;
        }

        List<Contact> contactsToUpdate = new List<Contact>();
        for (Contact c : [
            SELECT Id, AccountId, MailingCountry
            FROM Contact
            WHERE AccountId IN :changedAccountIds
        ]) {
            Account oldAcc = oldAccounts.get(c.AccountId);
            Account newAcc = newAccounts.get(c.AccountId);
            if (oldAcc == null || newAcc == null) {
                continue;
            }

            String oldCountry = oldAcc.BillingCountry;
            String newCountry = newAcc.BillingCountry;

            if (String.isBlank(c.MailingCountry) || isSameCountry(c.MailingCountry, oldCountry)) {
                if (!isSameCountry(c.MailingCountry, newCountry)) {
                    c.MailingCountry = newCountry;
                    contactsToUpdate.add(c);
                }
            }
        }

        if (!contactsToUpdate.isEmpty()) {
            update contactsToUpdate;
        }
    }

    private static Boolean isSameCountry(String a, String b) {
        if (String.isBlank(a) && String.isBlank(b)) {
            return true;
        }
        return a == b;
    }
}
