import { LightningElement, api } from 'lwc';
import { NavigationMixin } from 'lightning/navigation';
import { encodeDefaultFieldValues } from 'lightning/pageReferenceUtils';

const CASE_LIST_VIEW_API_NAME = 'My_Open_Cases';

export default class AccountQuickLinks extends NavigationMixin(LightningElement) {
    /** Account Id provided by the record page. */
    @api recordId;

    /** URL of the Case list view, generated with NavigationMixin.GenerateUrl. */
    casesListUrl;

    connectedCallback() {
        this.generateCasesListUrl();
    }

    get hasCasesListUrl() {
        return Boolean(this.casesListUrl);
    }

    async generateCasesListUrl() {
        try {
            this.casesListUrl = await this[NavigationMixin.GenerateUrl]({
                type: 'standard__objectPage',
                attributes: {
                    objectApiName: 'Case',
                    actionName: 'list'
                },
                state: {
                    filterName: CASE_LIST_VIEW_API_NAME
                }
            });
        } catch (error) {
            this.casesListUrl = undefined;
            // eslint-disable-next-line no-console
            console.error('accountQuickLinks: unable to generate the Case list view URL.', error);
        }
    }

    handleClick(event) {
        const action = event.currentTarget.dataset.action;

        switch (action) {
            case 'new-contact':
                this.navigateToNewContact();
                break;
            case 'contacts':
                this.navigateToRelatedContacts();
                break;
            case 'edit':
                this.navigateToEditAccount();
                break;
            default:
                break;
        }
    }

    /** Standard New Contact page with AccountId prefilled. */
    navigateToNewContact() {
        this[NavigationMixin.Navigate]({
            type: 'standard__objectPage',
            attributes: {
                objectApiName: 'Contact',
                actionName: 'new'
            },
            state: {
                defaultFieldValues: encodeDefaultFieldValues({
                    AccountId: this.recordId
                })
            }
        });
    }

    /** Account's related Contacts list. */
    navigateToRelatedContacts() {
        this[NavigationMixin.Navigate]({
            type: 'standard__recordRelationshipPage',
            attributes: {
                recordId: this.recordId,
                objectApiName: 'Account',
                relationshipApiName: 'Contacts',
                actionName: 'view'
            }
        });
    }

    /** Standard edit page of the account. */
    navigateToEditAccount() {
        this[NavigationMixin.Navigate]({
            type: 'standard__recordPage',
            attributes: {
                recordId: this.recordId,
                actionName: 'edit'
            }
        });
    }
}
