import { LightningElement } from 'lwc';

// Module-scoped counter: every instance of the component gets its own DOM id,
// so the button's `aria-controls` reference stays unique even when several
// collapsible sections are rendered on the same page.
let nextSectionId = 0;

/**
 * Reusable WAI-ARIA disclosure ("collapsible section").
 *
 * Usage:
 *   <c-collapsible-section>
 *       <span slot="title">Billing details</span>
 *       <p>Any body content…</p>
 *   </c-collapsible-section>
 */
export default class CollapsibleSection extends LightningElement {
    // Id of the element that the toggle button controls. Generated once per
    // instance; the matching `id` is rendered on the `.section-body` div.
    bodyId = `collapsible-section-body-${++nextSectionId}`;

    // The section starts collapsed.
    isOpen = false;

    // aria-expanded must be the literal strings "true"/"false" (a boolean
    // binding would drop the attribute when false, which is invalid ARIA).
    get ariaExpanded() {
        return this.isOpen ? 'true' : 'false';
    }

    // Drives the boolean `hidden` attribute on the body. The body element is
    // always rendered, so `aria-controls` always resolves to a real element.
    get isCollapsed() {
        return !this.isOpen;
    }

    // Native <button> already handles Enter/Space and click, so a single
    // click handler is all that is needed.
    handleToggle() {
        this.isOpen = !this.isOpen;
    }
}
