```js
import { LightningElement } from 'lwc';
import searchContacts from '@salesforce/apex/ContactController.searchContacts';

const DEBOUNCE_MS = 300;
const MIN_TERM_LENGTH = 2;
const FALLBACK_ERROR_MESSAGE = 'Something went wrong while searching contacts.';

export default class ContactSearch extends LightningElement {
    contacts = [];
    errorMessage;

    // Pending debounce timer id.
    _debounceTimer;
    // Monotonically increasing id of the newest dispatched request.
    _latestRequestId = 0;
    // Set when the component is removed from the DOM.
    _isDisconnected = false;

    get hasResults() {
        return this.contacts.length > 0;
    }

    get hasError() {
        return Boolean(this.errorMessage);
    }

    handleChange(event) {
        // `type="search"` fires change on every keystroke and on the clear (x) button.
        const searchTerm = (event.target.value || '').trim();

        // Any previously scheduled search is obsolete now.
        this._clearDebounceTimer();

        if (searchTerm.length < MIN_TERM_LENGTH) {
            // Cancel in-flight work too, so a late response cannot repopulate the list.
            this._invalidateInFlightRequest();
            this._clearResults();
            return;
        }

        this._debounceTimer = setTimeout(() => {
            this._debounceTimer = undefined;
            this._search(searchTerm);
        }, DEBOUNCE_MS);
    }

    disconnectedCallback() {
        // The component is gone: never fire the pending search and never touch state
        // from a response that is still on the wire.
        this._isDisconnected = true;
        this._clearDebounceTimer();
        this._invalidateInFlightRequest();
    }

    async _search(searchTerm) {
        if (this._isDisconnected) {
            return;
        }

        const requestId = ++this._latestRequestId;

        try {
            const results = await searchContacts({ searchTerm });

            // Out-of-order protection: only the newest request may update the UI.
            if (!this._isCurrentRequest(requestId)) {
                return;
            }

            this.contacts = results || [];
            this.errorMessage = undefined;
        } catch (error) {
            if (!this._isCurrentRequest(requestId)) {
                return;
            }

            this.contacts = [];
            this.errorMessage = this._getErrorMessage(error);
        }
    }

    _isCurrentRequest(requestId) {
        return !this._isDisconnected && requestId === this._latestRequestId;
    }

    _getErrorMessage(error) {
        if (error && error.body && error.body.message) {
            return error.body.message;
        }
        return FALLBACK_ERROR_MESSAGE;
    }

    _clearDebounceTimer() {
        if (this._debounceTimer !== undefined) {
            clearTimeout(this._debounceTimer);
            this._debounceTimer = undefined;
        }
    }

    _invalidateInFlightRequest() {
        this._latestRequestId += 1;
    }

    _clearResults() {
        this.contacts = [];
        this.errorMessage = undefined;
    }
}
