import { LightningElement, api } from 'lwc';

export default class OrderLinesPanel extends LightningElement {
    /** Array of { key, productName, quantity } */
    @api lines = [];

    /** True when the last submit found at least one invalid line. */
    showError = false;

    /** Child editors in display (DOM) order. */
    get editors() {
        return Array.from(this.template.querySelectorAll('c-line-item-editor'));
    }

    handleClick(event) {
        const action = event.currentTarget.dataset.action;
        if (action === 'reset') {
            this.handleReset();
        } else if (action === 'submit') {
            this.handleSubmit();
        }
    }

    handleReset() {
        this.editors.forEach((editor) => editor.reset());
    }

    handleSubmit() {
        const editors = this.editors;
        const values = [];
        let allValid = true;

        // Validate every editor (no short-circuiting) so that all invalid
        // lines show their error messages at once.
        editors.forEach((editor) => {
            const isValid = editor.validate();
            values.push(editor.getValue());
            if (!isValid) {
                allValid = false;
            }
        });

        if (allValid) {
            this.showError = false;
            this.dispatchEvent(
                new CustomEvent('submit', {
                    detail: { lines: values },
                    bubbles: true,
                    composed: true
                })
            );
        } else {
            this.showError = true;
        }
    }
}
