import { LightningElement } from 'lwc';
import getQueueStats from '@salesforce/apex/QueueController.getQueueStats';

const REFRESH_INTERVAL_MS = 60000;

export default class QueueMonitor extends LightningElement {
    // Rendered state
    waiting;
    longestWaitMinutes;
    hasStats = false;
    error;

    // Non-rendered state
    _pollId;
    _isLoading = false;
    _visibilityHandler;
    // Bumped on every mount/unmount so responses from a previous mount are ignored.
    _generation = 0;

    connectedCallback() {
        // A fresh mount always starts over with a single, clean polling loop.
        this._generation += 1;
        this._isLoading = false;

        if (!this._visibilityHandler) {
            this._visibilityHandler = this._handleVisibilityChange.bind(this);
            document.addEventListener('visibilitychange', this._visibilityHandler);
        }

        this._startPolling();
    }

    disconnectedCallback() {
        // Invalidate any in-flight response and stop everything: no timers, no listener, no Apex.
        this._generation += 1;
        this._isLoading = false;

        this._stopPolling();

        if (this._visibilityHandler) {
            document.removeEventListener('visibilitychange', this._visibilityHandler);
            this._visibilityHandler = undefined;
        }
    }

    get errorMessage() {
        const error = this.error;
        return (error && error.body && error.body.message) || 'Unknown error.';
    }

    _isPageHidden() {
        return document.visibilityState === 'hidden';
    }

    _startPolling() {
        // Never allow more than one polling loop.
        this._stopPolling();

        // Hidden tabs must not call Apex; the visibilitychange handler resumes us.
        if (this._isPageHidden()) {
            return;
        }

        // Load immediately, then refresh every 60 seconds.
        this._loadStats();

        this._pollId = window.setInterval(() => {
            this._handleTick();
        }, REFRESH_INTERVAL_MS);
    }

    _stopPolling() {
        if (this._pollId !== undefined) {
            window.clearInterval(this._pollId);
            this._pollId = undefined;
        }
    }

    _handleTick() {
        // Defensive: polling should already be stopped while hidden.
        if (this._isPageHidden()) {
            this._stopPolling();
            return;
        }
        this._loadStats();
    }

    _handleVisibilityChange() {
        if (this._isPageHidden()) {
            // Tab went to the background: stop polling so no requests are made.
            this._stopPolling();
        } else {
            // Tab is visible again: refresh immediately and resume the 60s cadence.
            this._startPolling();
        }
    }

    async _loadStats() {
        // Skip this refresh while the previous request is still in flight.
        if (this._isLoading) {
            return;
        }

        // Never start a request from a hidden tab.
        if (this._isPageHidden()) {
            return;
        }

        const generation = this._generation;
        this._isLoading = true;

        try {
            const stats = await getQueueStats();

            // Component was removed (or removed and re-inserted) while the call was in flight.
            if (generation !== this._generation) {
                return;
            }

            this.waiting = stats.waiting;
            this.longestWaitMinutes = stats.longestWaitMinutes;
            this.hasStats = true;
            // A successful refresh clears any previous error.
            this.error = undefined;
        } catch (error) {
            if (generation !== this._generation) {
                return;
            }
            // Keep polling; the error is cleared by the next successful refresh.
            this.error = error;
        } finally {
            if (generation === this._generation) {
                this._isLoading = false;
            }
        }
    }
}
