import { LightningElement } from 'lwc';
import register from '@salesforce/apex/RegistrationController.register';
import { ShowToastEvent } from 'lightning/platformShowToastEvent';

const FREE_EMAIL_DOMAINS = ['gmail.com', 'yahoo.com', 'hotmail.com', 'outlook.com'];

export default class EventRegistrationForm extends LightningElement {
    fullName = '';
    email = '';
    company = '';

    handleChange(event) {
        const field = event.target.dataset.field;
        if (field) {
            this[field] = event.detail.value;
        }
    }

    handleRegister() {
        const inputs = Array.from(this.template.querySelectorAll('lightning-input'));
        const emailInput = this.template.querySelector('[data-field="email"]');

        // 1. Work email check - must happen before validation is reported.
        if (emailInput) {
            const domain = this.getDomain(this.email);
            if (FREE_EMAIL_DOMAINS.includes(domain)) {
                emailInput.setCustomValidity('Use your work email address.');
            } else {
                emailInput.setCustomValidity('');
            }
        }

        // 2. Report validity on every input so all messages show at once.
        //    No short-circuiting: reportValidity() is called on each input.
        let allValid = true;
        inputs.forEach((input) => {
            const isValid = input.reportValidity();
            if (!isValid) {
                allValid = false;
            }
        });

        // 3. Stop when anything is invalid.
        if (!allValid) {
            return;
        }

        // 4. Call Apex imperatively.
        register({
            fullName: this.fullName,
            email: this.email,
            company: this.company
        })
            .then(() => {
                this.dispatchEvent(
                    new ShowToastEvent({
                        variant: 'success',
                        title: 'Registered'
                    })
                );
            })
            .catch((error) => {
                this.dispatchEvent(
                    new ShowToastEvent({
                        variant: 'error',
                        title: 'Registration failed',
                        message: error && error.body ? error.body.message : undefined
                    })
                );
            });
    }

    getDomain(value) {
        const email = (value || '').trim().toLowerCase();
        const atIndex = email.lastIndexOf('@');
        if (atIndex === -1) {
            return '';
        }
        return email.substring(atIndex + 1);
    }
}
