import { LightningElement, api } from 'lwc';

/** Keys that move the active option (selection is left untouched). */
const NAVIGATION_KEYS = new Set(['ArrowDown', 'ArrowUp', 'Home', 'End']);
/** Keys that select the active option. */
const SELECTION_KEYS = new Set(['Enter', ' ']);

// Option ids must be unique in the document, so every instance gets its own prefix.
let instanceCounter = 0;

export default class StatusListbox extends LightningElement {
    @api label;
    @api options = [];

    _value = '';
    _activeValue;
    _instanceId;

    constructor() {
        super();
        instanceCounter += 1;
        this._instanceId = `status-listbox-${instanceCounter}`;
    }

    @api
    get value() {
        return this._value;
    }

    set value(value) {
        const nextValue = value === undefined || value === null ? '' : value;
        this._value = nextValue;
        // The parent changed the selection, so the active option follows it.
        this._activeValue = nextValue;
    }

    get _optionList() {
        return Array.isArray(this.options) ? this.options : [];
    }

    /** Value of the option that aria-activedescendant points at. */
    get _resolvedActiveValue() {
        const optionList = this._optionList;
        if (optionList.length === 0) {
            return '';
        }

        const contains = (value) => optionList.some((option) => option.value === value);

        if (
            this._activeValue !== undefined &&
            this._activeValue !== null &&
            contains(this._activeValue)
        ) {
            return this._activeValue;
        }

        if (
            this._value !== '' &&
            this._value !== undefined &&
            this._value !== null &&
            contains(this._value)
        ) {
            return this._value;
        }

        // Nothing selected (or the selected value is not part of the list).
        return optionList[0].value;
    }

    get activeDescendantId() {
        const index = this._optionList.findIndex(
            (option) => option.value === this._resolvedActiveValue
        );
        return index === -1 ? undefined : this._optionId(index);
    }

    get renderedOptions() {
        const activeValue = this._resolvedActiveValue;

        return this._optionList.map((option, index) => {
            const isSelected = option.value === this._value;
            const isActive = option.value === activeValue;

            return {
                key: this._optionId(index),
                id: this._optionId(index),
                value: option.value,
                label: option.label,
                ariaSelected: isSelected ? 'true' : 'false',
                className: isActive
                    ? 'status-listbox__option status-listbox__option_active'
                    : 'status-listbox__option'
            };
        });
    }

    _optionId(index) {
        return `${this._instanceId}-option-${index}`;
    }

    handleKeyDown(event) {
        const { key } = event;
        const isNavigation = NAVIGATION_KEYS.has(key);
        const isSelection = SELECTION_KEYS.has(key);

        if (!isNavigation && !isSelection) {
            // Tab (and every other key) keeps its default behaviour.
            return;
        }

        event.preventDefault();

        const optionList = this._optionList;
        if (optionList.length === 0) {
            return;
        }

        const values = optionList.map((option) => option.value);
        let index = values.indexOf(this._resolvedActiveValue);
        if (index === -1) {
            index = 0;
        }

        if (key === 'ArrowDown') {
            index = Math.min(index + 1, values.length - 1);
        } else if (key === 'ArrowUp') {
            index = Math.max(index - 1, 0);
        } else if (key === 'Home') {
            index = 0;
        } else if (key === 'End') {
            index = values.length - 1;
        } else {
            // Enter or space: select the active option.
            this.selectOption(values[index]);
            return;
        }

        // Moving the active option never changes the selection.
        this._activeValue = values[index];
    }

    handleOptionClick(event) {
        this.selectOption(event.currentTarget.dataset.value);
    }

    selectOption(value) {
        this._activeValue = value;

        if (value === this._value) {
            // Already selected: nothing to dispatch.
            return;
        }

        this._value = value;

        this.dispatchEvent(
            new CustomEvent('change', {
                detail: { value },
                bubbles: true,
                composed: true
            })
        );
    }
}
