/**
 * EmployerService
 *
 * Sets the current employer for a set of Contacts by updating the Contact's
 * NPSP Primary Affiliation lookup. NPSP's standard affiliation automation
 * (AFL_Contact_TDTM) then:
 *   - creates or updates the Affiliation record to be Current and Primary,
 *   - marks any previous primary affiliation as Former, non-primary, with
 *     an EndDate of today,
 *   - keeps the Contact in their existing household Account.
 *
 * The method is bulk-safe and uses at most 1 SOQL query and 1 DML statement
 * of its own.
 */
public with sharing class EmployerService {

    /**
     * @param employerByContactId Map of Contact Id -> Organization Account Id.
     *        A null or empty map results in no action.
     */
    public static void setCurrentEmployers(Map<Id, Id> employerByContactId) {
        if (employerByContactId == null || employerByContactId.isEmpty()) {
            return;
        }

        // Single SOQL: fetch the current primary affiliation for the contacts.
        Map<Id, Contact> contacts = new Map<Id, Contact>([
            SELECT Id, npsp__Primary_Affiliation__c
            FROM Contact
            WHERE Id IN :employerByContactId.keySet()
        ]);

        List<Contact> contactsToUpdate = new List<Contact>();

        for (Id contactId : employerByContactId.keySet()) {
            Id employerId = employerByContactId.get(contactId);

            // Skip null employer values (no change requested).
            if (employerId == null) {
                continue;
            }

            Contact c = contacts.get(contactId);

            // Skip contacts that don't exist or aren't accessible.
            if (c == null) {
                continue;
            }

            // If the organization is already the primary affiliation, do nothing.
            if (c.npsp__Primary_Affiliation__c == employerId) {
                continue;
            }

            // Update only the primary affiliation lookup. NPSP handles the
            // affiliation record creation/update and former-affiliation logic.
            contactsToUpdate.add(new Contact(
                Id = contactId,
                npsp__Primary_Affiliation__c = employerId
            ));
        }

        // Single DML: update all contacts in one call.
        if (!contactsToUpdate.isEmpty()) {
            update contactsToUpdate;
        }
    }
}
