public with sharing class GauAllocationService {
    public class AllocationException extends Exception {}

    public static List<npsp__Allocation__c> allocateByPercent(Id opportunityId, Map<Id, Decimal> percentByGauId) {
        if (opportunityId == null) {
            throw new AllocationException('Opportunity Id is required.');
        }
        if (percentByGauId == null || percentByGauId.isEmpty()) {
            throw new AllocationException('Percent by GAU map is required and cannot be empty.');
        }

        Decimal totalPercent = 0;
        for (Id gauId : percentByGauId.keySet()) {
            if (gauId == null) {
                throw new AllocationException('GAU Id cannot be null.');
            }
            Decimal pct = percentByGauId.get(gauId);
            if (pct == null || pct <= 0) {
                throw new AllocationException('Percentage must be greater than zero.');
            }
            totalPercent += pct;
        }

        if (totalPercent > 100) {
            throw new AllocationException('Total percentage cannot exceed 100.');
        }

        Map<Id, npsp__General_Accounting_Unit__c> gaus = new Map<Id, npsp__General_Accounting_Unit__c>(
            [SELECT Id, npsp__Active__c FROM npsp__General_Accounting_Unit__c WHERE Id IN :percentByGauId.keySet()]
        );

        for (Id gauId : percentByGauId.keySet()) {
            npsp__General_Accounting_Unit__c gau = gaus.get(gauId);
            if (gau == null || !gau.npsp__Active__c) {
                throw new AllocationException('GAU is inactive or does not exist: ' + gauId);
            }
        }

        List<npsp__Allocation__c> existingAllocations = [
            SELECT Id FROM npsp__Allocation__c WHERE npsp__Opportunity__c = :opportunityId
        ];
        if (!existingAllocations.isEmpty()) {
            delete existingAllocations;
        }

        List<npsp__Allocation__c> newAllocations = new List<npsp__Allocation__c>();
        for (Id gauId : percentByGauId.keySet()) {
            newAllocations.add(new npsp__Allocation__c(
                npsp__Opportunity__c = opportunityId,
                npsp__General_Accounting_Unit__c = gauId,
                npsp__Percent__c = percentByGauId.get(gauId)
            ));
        }

        insert newAllocations;

        List<Id> newIds = new List<Id>();
        for (npsp__Allocation__c alloc : newAllocations) {
            newIds.add(alloc.Id);
        }

        return [
            SELECT Id, npsp__Opportunity__c, npsp__General_Accounting_Unit__c, npsp__Amount__c, npsp__Percent__c
            FROM npsp__Allocation__c
            WHERE Id IN :newIds
        ];
    }
}
