                SELECT Id, FirstName, LastName, AccountId
                FROM Contact
                WHERE Id = :contactId
                LIMIT 1
            ];
        } catch (QueryException e) {
            throw new IllegalArgumentException('Contact does not exist: ' + contactId);
        }

        if (donor == null) {
            throw new IllegalArgumentException('Contact does not exist: ' + contactId);
        }
        if (donor.AccountId == null) {
            throw new IllegalArgumentException('Contact has no household account: ' + contactId);
        }

        Id householdId = donor.AccountId;

        List<Contact> householdMembers = [
            SELECT Id
            FROM Contact
            WHERE AccountId = :householdId
            ORDER BY Id
        ];

        Set<Id> memberIds = new Set<Id>();
        for (Contact c : householdMembers) {
            memberIds.add(c.Id);
        }
        if (!memberIds.contains(contactId)) {
            memberIds.add(contactId);
        }

        String donorName = ((String.isBlank(donor.FirstName) ? '' : donor.FirstName + ' ') + donor.LastName).trim();
        String oppName = donorName + ' Donation ' + String.valueOf(giftDate);

        Opportunity opp = new Opportunity(
            Name = oppName,
            AccountId = householdId,
            StageName = STAGE_CLOSED_WON,
            CloseDate = giftDate,
            Amount = amount,
            npsp__Primary_Contact__c = contactId
        );
        insert opp;

        List<OpportunityContactRole> existingRoles = [
            SELECT Id
            FROM OpportunityContactRole
            WHERE OpportunityId = :opp.Id
        ];
        if (!existingRoles.isEmpty()) {
            delete existingRoles;
        }

        List<OpportunityContactRole> newRoles = new List<OpportunityContactRole>();
        for (Id memberId : memberIds) {
            newRoles.add(new OpportunityContactRole(
                OpportunityId = opp.Id,
                ContactId = memberId,
                Role = memberId == contactId ? ROLE_DONOR : ROLE_HOUSEHOLD_MEMBER
            ));
        }
        if (!newRoles.isEmpty()) {
            insert newRoles;
        }

        List<npe01__OppPayment__c> existingPayments = [
            SELECT Id, npe01__Paid__c, npe01__Payment_Amount__c, npe01__Payment_Date__c, npe01__Scheduled_Date__c
            FROM npe01__OppPayment__c
            WHERE npe01__Opportunity__c = :opp.Id
            ORDER BY CreatedDate
        ];

        if (existingPayments.isEmpty()) {
            insert new npe01__OppPayment__c(
                npe01__Opportunity__c = opp.Id,
                npe01__Payment_Amount__c = amount,
                npe01__Payment_Date__c = giftDate,
                npe01__Scheduled_Date__c = giftDate,
                npe01__Paid__c = true
            );
        } else {
            npe01__OppPayment__c payment = existingPayments[0];
            payment.npe01__Payment_Amount__c = amount;
            payment.npe01__Payment_Date__c = giftDate;
            payment.npe01__Scheduled_Date__c = giftDate;
            payment.npe01__Paid__c = true;
            update payment;

            if (existingPayments.size() > 1) {
                List<npe01__OppPayment__c> duplicates = new List<npe01__OppPayment__c>();
                for (Integer i = 1; i < existingPayments.size(); i++) {
                    duplicates.add(existingPayments[i]);
                }
                delete duplicates;
            }
        }

        return opp.Id;
    }
}
