global class OPP_MajorGiftFollowUp_TDTM extends npsp.TDTM_Runnable {

    global override npsp.TDTM_Runnable.DmlWrapper run(List<SObject> newlist, List<SObject> oldlist,
        npsp.TDTM_Runnable.Action triggerAction, Schema.DescribeSObjectResult objResult) {

        npsp.TDTM_Runnable.DmlWrapper dmlWrapper = new npsp.TDTM_Runnable.DmlWrapper();
        List<Task> tasksToInsert = new List<Task>();

        // Build a map of old opportunities for AfterUpdate. For AfterInsert, oldlist is null.
        Map<Id, Opportunity> oldOppsById = new Map<Id, Opportunity>();
        if (oldlist != null) {
            for (SObject so : oldlist) {
                Opportunity oldOpp = (Opportunity) so;
                oldOppsById.put(oldOpp.Id, oldOpp);
            }
        }

        for (SObject so : newlist) {
            Opportunity newOpp = (Opportunity) so;
            Opportunity oldOpp = oldOppsById.get(newOpp.Id);

            Boolean wasQualified = oldOpp != null && qualifies(oldOpp);
            Boolean isQualified = qualifies(newOpp);

            // Create a task only when the opportunity newly qualifies.
            if (isQualified && !wasQualified) {
                tasksToInsert.add(createFollowUpTask(newOpp));
            }
        }

        if (!tasksToInsert.isEmpty()) {
            dmlWrapper.objectsToInsert.addAll(tasksToInsert);
        }

        return dmlWrapper;
    }

    private Boolean qualifies(Opportunity opp) {
        return opp != null
            && opp.IsWon
            && opp.Amount != null
            && opp.Amount >= 5000;
    }

    private Task createFollowUpTask(Opportunity opp) {
        Task t = new Task();
        t.Subject = 'Major gift thank-you call';
        t.Priority = 'High';
        t.Status = 'Not Started';
        t.WhatId = opp.Id;
        t.WhoId = opp.npsp__Primary_Contact__c;
        t.OwnerId = opp.OwnerId;
        if (opp.CloseDate != null) {
            t.ActivityDate = opp.CloseDate.addDays(3);
        }
        return t;
    }
}
