```apex
/**
 * Trigger Action: creates an onboarding Task for the owner of a newly created Account
 * whose Type is "Customer - Direct" or "Customer - Channel".
 *
 * Registered in Trigger_Action__mdt (DeveloperName: TA_Account_CreateOnboardingTask)
 * against the Account sObject trigger setting for the After Insert context only.
 *
 * Bulk-safe: at most one DML statement per trigger execution, and no DML at all when
 * no inserted Account qualifies.
 */
public with sharing class TA_Account_CreateOnboardingTask implements TriggerAction.AfterInsert {
    private static final String TASK_SUBJECT = 'Onboard new customer';
    private static final String TASK_STATUS = 'Not Started';
    private static final String TASK_PRIORITY = 'Normal';
    private static final Integer TASK_DUE_IN_DAYS = 7;

    private static final Set<String> ONBOARDING_ACCOUNT_TYPES = new Set<String>{
        'Customer - Direct',
        'Customer - Channel'
    };

    public void afterInsert(List<SObject> triggerNew) {
        if (triggerNew == null || triggerNew.isEmpty()) {
            return;
        }

        Date dueDate = Date.today().addDays(TASK_DUE_IN_DAYS);
        List<Task> tasksToInsert = new List<Task>();

        for (Account acct : (List<Account>) triggerNew) {
            if (acct.Type != null && ONBOARDING_ACCOUNT_TYPES.contains(acct.Type)) {
                tasksToInsert.add(
                    new Task(
                        Subject = TASK_SUBJECT,
                        WhatId = acct.Id,
                        OwnerId = acct.OwnerId,
                        ActivityDate = dueDate,
                        Status = TASK_STATUS,
                        Priority = TASK_PRIORITY
                    )
                );
            }
        }

        // Single DML statement for the whole trigger execution, skipped entirely when
        // no Account qualified.
        if (!tasksToInsert.isEmpty()) {
            insert tasksToInsert;
        }
    }
}
