/**
 * AccountOwnershipService
 *
 * Moves a book of business: reassigns the owner of a set of Accounts and of every Contact
 * that belongs to those Accounts.
 *
 * The Account trigger actions (territory recalculation) are expensive and are irrelevant to a
 * pure ownership change, so the Trigger Actions Framework transaction bypass is used for the
 * whole Account sObject while the change is applied. Contact trigger actions still run
 * normally. The bypass is cleared in a finally block, so Account automation behaves normally
 * for the rest of the transaction whether or not the DML succeeded.
 */
public with sharing class AccountOwnershipService {
    /**
     * Sets OwnerId = newOwnerId on the given Accounts and on all Contacts of those Accounts.
     *
     * @param accountIds  the Accounts to reassign (up to 200 per call)
     * @param newOwnerId  the User who becomes the owner of the Accounts and of their Contacts
     */
    public static void reassign(Set<Id> accountIds, Id newOwnerId) {
        Set<Id> targetAccountIds = new Set<Id>();
        if (accountIds != null) {
            for (Id accountId : accountIds) {
                if (accountId != null) {
                    targetAccountIds.add(accountId);
                }
            }
        }
        if (targetAccountIds.isEmpty()) {
            return;
        }

        // One query for every Contact of every Account, whatever the number of Accounts.
        List<Contact> contactsToUpdate = new List<Contact>();
        for (Contact contactRecord : [
            SELECT Id, OwnerId
            FROM Contact
            WHERE AccountId IN :targetAccountIds
        ]) {
            contactRecord.OwnerId = newOwnerId;
            contactsToUpdate.add(contactRecord);
        }

        List<Account> accountsToUpdate = new List<Account>();
        for (Id accountId : targetAccountIds) {
            accountsToUpdate.add(new Account(Id = accountId, OwnerId = newOwnerId));
        }

        // TAF transaction bypass for the whole Account sObject: no Account trigger action
        // (territory recalculation) runs for this ownership change. Contact automation is
        // untouched and runs normally.
        TriggerBase.bypass(Account.SObjectType);
        try {
            // Accounts first, so that Contact trigger actions see the new Account owner.
            // DML statements are all-or-none and exceptions propagate unchanged to the caller.
            update accountsToUpdate;
            update contactsToUpdate;
        } finally {
            // Success or failure: Account automation behaves normally for the rest of the
            // transaction.
            TriggerBase.clearBypass(Account.SObjectType);
        }
    }
}
