/**
 * DML-less unit tests for TA_Opportunity_GuardAmountDecrease.
 *
 * The Trigger Actions Framework recommends testing trigger actions by calling the action's
 * context method directly with in-memory records instead of inserting and updating data.
 * This class therefore contains no DML and no SOQL: the new and old records are built in
 * memory, given fake Ids with the framework's TriggerTestUtility (so that the action's
 * Id-based lookup of the previous values resolves), and handed straight to beforeUpdate.
 */
@IsTest
private class TA_Opportunity_GuardAmountDecreaseTest {
    private static final Decimal PREVIOUS_AMOUNT = 1000;

    @IsTest
    static void rejectsDecreaseOfMoreThanHalf() {
        Opportunity oldOpportunity = buildOpportunity(PREVIOUS_AMOUNT);
        Opportunity newOpportunity = buildOpportunity(499, oldOpportunity.Id);

        new TA_Opportunity_GuardAmountDecrease()
            .beforeUpdate(new List<Opportunity>{ newOpportunity }, new List<Opportunity>{ oldOpportunity });

        Assert.isTrue(newOpportunity.hasErrors(), 'A decrease of more than half must be rejected.');
        Assert.areEqual(1, newOpportunity.getErrors().size(), 'Exactly one error must be added.');
        Assert.areEqual(
            TA_Opportunity_GuardAmountDecrease.ERROR_MESSAGE,
            newOpportunity.getErrors()[0].getMessage(),
            'The error must carry the action\'s ERROR_MESSAGE.'
        );
    }

    @IsTest
    static void acceptsDecreaseOfExactlyHalf() {
        Opportunity oldOpportunity = buildOpportunity(PREVIOUS_AMOUNT);
        Opportunity newOpportunity = buildOpportunity(PREVIOUS_AMOUNT / 2, oldOpportunity.Id);

        new TA_Opportunity_GuardAmountDecrease()
            .beforeUpdate(new List<Opportunity>{ newOpportunity }, new List<Opportunity>{ oldOpportunity });

        Assert.isFalse(newOpportunity.hasErrors(), 'A decrease of exactly half is allowed.');
        Assert.areEqual(0, newOpportunity.getErrors().size(), 'No error must be added.');
    }

    @IsTest
    static void acceptsIncrease() {
        Opportunity oldOpportunity = buildOpportunity(PREVIOUS_AMOUNT);
        Opportunity newOpportunity = buildOpportunity(PREVIOUS_AMOUNT + 500, oldOpportunity.Id);

        new TA_Opportunity_GuardAmountDecrease()
            .beforeUpdate(new List<Opportunity>{ newOpportunity }, new List<Opportunity>{ oldOpportunity });

        Assert.isFalse(newOpportunity.hasErrors(), 'An increase is allowed.');
        Assert.areEqual(0, newOpportunity.getErrors().size(), 'No error must be added.');
    }

    @IsTest
    static void acceptsWhenPreviousAmountIsNull() {
        Opportunity oldOpportunity = buildOpportunity(null);
        Opportunity newOpportunity = buildOpportunity(100, oldOpportunity.Id);

        new TA_Opportunity_GuardAmountDecrease()
            .beforeUpdate(new List<Opportunity>{ newOpportunity }, new List<Opportunity>{ oldOpportunity });

        Assert.isFalse(newOpportunity.hasErrors(), 'A null previous Amount cannot be reduced by more than half.');
        Assert.areEqual(0, newOpportunity.getErrors().size(), 'No error must be added.');
    }

    @IsTest
    static void bulkUpdateRejectsOnlyTheRecordsThatBreakTheRule() {
        List<Opportunity> triggerOld = new List<Opportunity>();
        List<Opportunity> triggerNew = new List<Opportunity>();

        // More than half of 1000 removed: rejected.
        Opportunity oldMoreThanHalf = buildOpportunity(1000);
        Opportunity newMoreThanHalf = buildOpportunity(400, oldMoreThanHalf.Id);
        triggerOld.add(oldMoreThanHalf);
        triggerNew.add(newMoreThanHalf);

        // Less than half of 2000 removed: accepted.
        Opportunity oldLessThanHalf = buildOpportunity(2000);
        Opportunity newLessThanHalf = buildOpportunity(1200, oldLessThanHalf.Id);
        triggerOld.add(oldLessThanHalf);
        triggerNew.add(newLessThanHalf);

        // Exactly half of 1000 removed: accepted.
        Opportunity oldExactlyHalf = buildOpportunity(1000);
        Opportunity newExactlyHalf = buildOpportunity(500, oldExactlyHalf.Id);
        triggerOld.add(oldExactlyHalf);
        triggerNew.add(newExactlyHalf);

        new TA_Opportunity_GuardAmountDecrease().beforeUpdate(triggerNew, triggerOld);

        Assert.isTrue(newMoreThanHalf.hasErrors(), 'The record reduced by more than half must be rejected.');
        Assert.areEqual(1, newMoreThanHalf.getErrors().size(), 'Exactly one error must be added.');
        Assert.areEqual(
            TA_Opportunity_GuardAmountDecrease.ERROR_MESSAGE,
            newMoreThanHalf.getErrors()[0].getMessage(),
            'The error must carry the action\'s ERROR_MESSAGE.'
        );

        Assert.isFalse(newLessThanHalf.hasErrors(), 'A decrease of less than half must not be rejected.');
        Assert.areEqual(0, newLessThanHalf.getErrors().size(), 'No error must be added.');

        Assert.isFalse(newExactlyHalf.hasErrors(), 'A decrease of exactly half must not be rejected.');
        Assert.areEqual(0, newExactlyHalf.getErrors().size(), 'No error must be added.');
    }

    private static Opportunity buildOpportunity(Decimal amount) {
        return buildOpportunity(amount, TriggerTestUtility.getFakeId(Opportunity.SObjectType));
    }

    private static Opportunity buildOpportunity(Decimal amount, Id recordId) {
        return new Opportunity(Id = recordId, Amount = amount);
    }
}
