/**
 * Trigger Action for the Trigger Actions Framework (v0.3.4).
 *
 * Rule: two Contacts of the same Account may not share an email address
 * (compared case-insensitively). Contacts without an Account or without an
 * Email are not checked.
 *
 * Behaviour:
 *  - Before insert: every Contact that has an Account and an Email is checked.
 *  - Before update: only Contacts whose Email or AccountId actually changed are
 *    checked, so pre-existing legacy duplicates never block unrelated edits.
 *  - Within a single save, the first Contact of an (AccountId, Email) pair is
 *    accepted and every later one gets a record level error.
 *  - A Contact never conflicts with itself.
 *  - Bulk safe: at most one SOQL query per trigger execution, for any batch size.
 *
 * Registered in Trigger_Action__mdt:
 *  - TA_Contact_PreventDuplicateEmail_BI -> Before_Insert__c = Contact, Order__c = 10
 *  - TA_Contact_PreventDuplicateEmail_BU -> Before_Update__c = Contact, Order__c = 10
 */
public with sharing class TA_Contact_PreventDuplicateEmail
        implements TriggerAction.BeforeInsert, TriggerAction.BeforeUpdate {

    private static final String DUPLICATE_EMAIL_ERROR =
            'Another contact on this account already uses this email address.';

    /**
     * @description Trigger Actions Framework before insert entry point.
     */
    public void beforeInsert(List<SObject> newRecords) {
        preventDuplicateEmails((List<Contact>) newRecords, null);
    }

    /**
     * @description Trigger Actions Framework before update entry point.
     */
    public void beforeUpdate(List<SObject> newRecords, List<SObject> oldRecords) {
        preventDuplicateEmails((List<Contact>) newRecords, (List<Contact>) oldRecords);
    }

    /**
     * @description Applies the duplicate email rule to the records in the current
     *              trigger execution. Only ever runs one SOQL query.
     */
    private static void preventDuplicateEmails(List<Contact> newContacts, List<Contact> oldContacts) {
        Map<Id, Contact> oldContactsById = oldContacts == null
                ? new Map<Id, Contact>()
                : new Map<Id, Contact>(oldContacts);

        List<Contact> contactsToCheck = new List<Contact>();
        Set<Id> accountIds = new Set<Id>();
        Set<String> emailAddresses = new Set<String>();

        for (Contact candidate : newContacts) {
            // Contacts without an Account or without an Email are not checked.
            if (candidate.AccountId == null || String.isBlank(candidate.Email)) {
                continue;
            }

            // On update, only records whose Email or AccountId changed are checked.
            if (oldContactsById.containsKey(candidate.Id)) {
                Contact previous = oldContactsById.get(candidate.Id);
                Boolean emailChanged =
                        normalizeEmail(candidate.Email) != normalizeEmail(previous.Email);
                Boolean accountChanged = candidate.AccountId != previous.AccountId;
                if (!emailChanged && !accountChanged) {
                    continue;
                }
            }

            contactsToCheck.add(candidate);
            accountIds.add(candidate.AccountId);
            emailAddresses.add(candidate.Email.trim());
        }

        if (contactsToCheck.isEmpty()) {
            return;
        }

        // Exactly one SOQL query for the whole trigger execution.
        Map<String, List<Id>> existingIdsByKey = new Map<String, List<Id>>();
        for (Contact existing : [
                SELECT Id, AccountId, Email
                FROM Contact
                WHERE AccountId IN :accountIds
                AND Email IN :emailAddresses
        ]) {
            String key = buildKey(existing.AccountId, existing.Email);
            if (!existingIdsByKey.containsKey(key)) {
                existingIdsByKey.put(key, new List<Id>());
            }
            existingIdsByKey.get(key).add(existing.Id);
        }

        Set<String> keysAcceptedInThisSave = new Set<String>();

        for (Contact candidate : contactsToCheck) {
            String key = buildKey(candidate.AccountId, candidate.Email);

            if (isDuplicate(key, candidate.Id, existingIdsByKey, keysAcceptedInThisSave)) {
                // Record level error: valid Contacts in the same save are unaffected.
                candidate.addError(DUPLICATE_EMAIL_ERROR);
            } else {
                keysAcceptedInThisSave.add(key);
            }
        }
    }

    /**
     * @description True when the (AccountId, Email) key is already used by another
     *              stored Contact or by an earlier Contact accepted in this save.
     */
    private static Boolean isDuplicate(
            String key,
            Id candidateId,
            Map<String, List<Id>> existingIdsByKey,
            Set<String> keysAcceptedInThisSave) {

        if (keysAcceptedInThisSave.contains(key)) {
            return true;
        }

        List<Id> existingIds = existingIdsByKey.get(key);
        if (existingIds != null) {
            for (Id existingId : existingIds) {
                // A Contact never conflicts with itself.
                if (existingId != candidateId) {
                    return true;
                }
            }
        }
        return false;
    }

    private static String buildKey(Id accountId, String email) {
        return String.valueOf(accountId) + '::' + normalizeEmail(email);
    }

    private static String normalizeEmail(String email) {
        return email == null ? '' : email.trim().toLowerCase();
    }
}
