/**
 * Trigger Action registered on Lead (Before Insert, order 10).
 *
 * Normalizes messy web-to-lead / list-import data before the record is saved:
 *  - Email:      trimmed and lower-cased (null stays null)
 *  - Company:    trimmed
 *  - LeadSource: blank/null -> 'Web', otherwise left untouched
 *
 * Bulk safe: single pass over Trigger.new, no SOQL and no DML, so the values are
 * already clean when the 200-record insert (or any size insert) is committed.
 */
public with sharing class TA_Lead_NormalizeContactInfo implements TriggerAction.BeforeInsert {
    private static final String DEFAULT_LEAD_SOURCE = 'Web';

    public void beforeInsert(List<SObject> triggerNew) {
        for (SObject record : triggerNew) {
            Lead newLead = (Lead) record;

            if (newLead.Email != null) {
                newLead.Email = newLead.Email.trim().toLowerCase();
            }

            if (newLead.Company != null) {
                newLead.Company = newLead.Company.trim();
            }

            if (String.isBlank(newLead.LeadSource)) {
                newLead.LeadSource = DEFAULT_LEAD_SOURCE;
            }
        }
    }
}
