/**
 * Case trigger action that keeps Account.FB_Open_Case_Count__c equal to the number of
 * the account's Cases whose IsClosed field is false.
 *
 * Registered in Trigger_Action__mdt against the Case sObject in the after insert,
 * after update, after delete and after undelete contexts, so it covers cases that are
 * created (open or already closed), closed, reopened, moved to another account, deleted
 * and undeleted. Cases without an account are ignored, and an account whose last open
 * case goes away is written as 0 rather than being left blank.
 *
 * Bulk safe: 200 cases per trigger execution, two SOQL queries and at most one DML
 * statement. The class runs without sharing, exactly like a native roll-up summary
 * field, so the stored count reflects the data rather than the running user's record
 * access.
 */
public without sharing class TA_Case_RollupOpenCount implements
        TriggerAction.AfterInsert,
        TriggerAction.AfterUpdate,
        TriggerAction.AfterDelete,
        TriggerAction.AfterUndelete {

    public void afterInsert(List<SObject> triggerNew) {
        recalculate(collectAccountIds(triggerNew, null));
    }

    public void afterUpdate(List<SObject> triggerNew, List<SObject> triggerOld) {
        // A reparented case affects both its previous and its new account.
        recalculate(collectAccountIds(triggerNew, triggerOld));
    }

    public void afterDelete(List<SObject> triggerOld) {
        recalculate(collectAccountIds(null, triggerOld));
    }

    public void afterUndelete(List<SObject> triggerNew) {
        recalculate(collectAccountIds(triggerNew, null));
    }

    /**
     * @return every account id touched by the records being processed. Cases that have
     *         no account are ignored.
     */
    private static Set<Id> collectAccountIds(List<SObject> triggerNew, List<SObject> triggerOld) {
        Set<Id> accountIds = new Set<Id>();
        addAccountIds(triggerNew, accountIds);
        addAccountIds(triggerOld, accountIds);
        return accountIds;
    }

    private static void addAccountIds(List<SObject> records, Set<Id> accountIds) {
        if (records == null) {
            return;
        }
        for (SObject record : records) {
            Id accountId = (Id) record.get(Case.AccountId);
            if (accountId != null) {
                accountIds.add(accountId);
            }
        }
    }

    private static void recalculate(Set<Id> accountIds) {
        if (accountIds.isEmpty()) {
            return;
        }

        // Query 1: the current number of open cases for every affected account.
        // Accounts with no open case at all are simply absent from the result and are
        // therefore treated as 0 below.
        Map<Id, Integer> openCaseCountByAccountId = new Map<Id, Integer>();
        for (AggregateResult result : [
                SELECT AccountId, COUNT(Id) openCaseCount
                FROM Case
                WHERE IsClosed = false
                AND AccountId IN :accountIds
                GROUP BY AccountId]) {
            openCaseCountByAccountId.put(
                    (Id) result.get('AccountId'),
                    (Integer) result.get('openCaseCount'));
        }

        // Query 2: the stored counts, so unchanged accounts are left untouched and
        // accounts that no longer exist are skipped instead of blowing up the DML.
        Map<Id, Account> accountsById = new Map<Id, Account>([
                SELECT Id, FB_Open_Case_Count__c
                FROM Account
                WHERE Id IN :accountIds]);

        List<Account> accountsToUpdate = new List<Account>();
        for (Id accountId : accountsById.keySet()) {
            Integer openCaseCount = openCaseCountByAccountId.containsKey(accountId)
                    ? openCaseCountByAccountId.get(accountId)
                    : 0;
            // A null stored value is never equal to a number, so a blank count is
            // rewritten as 0 as well.
            if (accountsById.get(accountId).FB_Open_Case_Count__c != openCaseCount) {
                accountsToUpdate.add(new Account(
                        Id = accountId,
                        FB_Open_Case_Count__c = openCaseCount));
            }
        }

        // One DML statement for every account whose count actually changed.
        if (!accountsToUpdate.isEmpty()) {
            update accountsToUpdate;
        }
    }
}
