/**
 * TA_Contact_Queries
 *
 * Shared-query singleton for the Contact trigger actions.
 *
 * The Trigger Actions Framework instantiates the inner `Service` class in the before insert
 * context so that the parent Accounts for the Contacts being inserted are queried exactly
 * once per trigger execution. Every other action simply reads the cached records from
 * `accountsById` and never issues its own SOQL statement.
 *
 * Registered with Order__c = 1 so that it always runs before the actions that consume it.
 */
public with sharing class TA_Contact_Queries {
    private static TA_Contact_Queries instance;

    /**
     * Parent Accounts of the Contacts currently being processed, keyed by Account Id.
     * Empty (never null) when no Contact in the current trigger execution has an Account.
     */
    public Map<Id, Account> accountsById { get; private set; }

    private TA_Contact_Queries() {
        this.accountsById = new Map<Id, Account>();
    }

    public static TA_Contact_Queries getInstance() {
        if (instance == null) {
            instance = new TA_Contact_Queries();
        }
        return instance;
    }

    /**
     * Replaces the cached map with a fresh query on every trigger execution. The map is not
     * reused between executions because later DML in the same transaction can involve other
     * Accounts than the ones referenced by the records of this execution.
     */
    private void loadAccounts(List<Contact> contacts) {
        Set<Id> accountIds = new Set<Id>();
        for (Contact newContact : contacts) {
            if (newContact.AccountId != null) {
                accountIds.add(newContact.AccountId);
            }
        }

        Map<Id, Account> parentAccounts = new Map<Id, Account>();
        if (!accountIds.isEmpty()) {
            parentAccounts = new Map<Id, Account>(
                [
                    SELECT
                        Id,
                        BillingStreet,
                        BillingCity,
                        BillingPostalCode,
                        BillingCountry,
                        AccountSource
                    FROM Account
                    WHERE Id IN :accountIds
                ]
            );
        }
        this.accountsById = parentAccounts;
    }

    /**
     * Trigger action that performs the single Account query for the before insert context.
     */
    public class Service implements TriggerAction.BeforeInsert {
        public void beforeInsert(List<SObject> triggerNew) {
            TA_Contact_Queries.getInstance().loadAccounts((List<Contact>) triggerNew);
        }
    }
}
