/**
 * TA_Contact_InheritMailingAddress
 *
 * Before insert: when a new Contact has an Account and all four of MailingStreet,
 * MailingCity, MailingPostalCode and MailingCountry are blank, copy the parent Account's
 * BillingStreet, BillingCity, BillingPostalCode and BillingCountry onto the Contact.
 * A Contact with any mailing address field populated keeps its own address, and a Contact
 * without an Account is left untouched.
 *
 * The parent Accounts are supplied by TA_Contact_Queries (Order__c = 1); this action never
 * issues its own query.
 */
public with sharing class TA_Contact_InheritMailingAddress implements TriggerAction.BeforeInsert {
    public void beforeInsert(List<SObject> triggerNew) {
        Map<Id, Account> accountsById = TA_Contact_Queries.getInstance().accountsById;

        for (SObject record : triggerNew) {
            Contact newContact = (Contact) record;

            if (newContact.AccountId == null) {
                continue;
            }

            // Any populated mailing field means the Contact keeps its own address.
            if (
                !String.isBlank(newContact.MailingStreet) ||
                !String.isBlank(newContact.MailingCity) ||
                !String.isBlank(newContact.MailingPostalCode) ||
                !String.isBlank(newContact.MailingCountry)
            ) {
                continue;
            }

            Account parentAccount = accountsById.get(newContact.AccountId);
            if (parentAccount == null) {
                continue;
            }

            newContact.MailingStreet = parentAccount.BillingStreet;
            newContact.MailingCity = parentAccount.BillingCity;
            newContact.MailingPostalCode = parentAccount.BillingPostalCode;
            newContact.MailingCountry = parentAccount.BillingCountry;
        }
    }
}
