/**
 * TA_Contact_DefaultLeadSource
 *
 * Before insert: when a new Contact has an Account and a blank LeadSource, set the
 * LeadSource to the parent Account's AccountSource. A Contact without an Account, or with
 * a LeadSource already populated, is left untouched.
 *
 * The parent Accounts are supplied by TA_Contact_Queries (Order__c = 1); this action never
 * issues its own query.
 */
public with sharing class TA_Contact_DefaultLeadSource implements TriggerAction.BeforeInsert {
    public void beforeInsert(List<SObject> triggerNew) {
        Map<Id, Account> accountsById = TA_Contact_Queries.getInstance().accountsById;

        for (SObject record : triggerNew) {
            Contact newContact = (Contact) record;

            if (newContact.AccountId == null || !String.isBlank(newContact.LeadSource)) {
                continue;
            }

            Account parentAccount = accountsById.get(newContact.AccountId);
            if (parentAccount == null || String.isBlank(parentAccount.AccountSource)) {
                continue;
            }

            newContact.LeadSource = parentAccount.AccountSource;
        }
    }
}
